const item = $input.first().json.result.item;
const file = item.ufCrm8QuotationDocx;
const fileObj = Array.isArray(file) ? file[0] : file;
const url = fileObj.urlMachine || fileObj.url || fileObj.downloadUrl;
return [{ json: { itemId: item.id, fileUrl: url, stageId: item.stageId } }];

const inp = $input.first();
const headers = inp.json?.headers || {};
let contentType = (headers['content-type'] || headers['Content-Type'] || '').toLowerCase();
let disposition = headers['content-disposition'] || headers['Content-Disposition'] || '';
let fileName = 'file';
const m = disposition.match(/filename\*?=(?:UTF-8'')?"?([^";]+)"?/i);
if (m) fileName = decodeURIComponent(m[1]);
let format = 'other';
let mimeType = 'application/octet-stream';
if (contentType.startsWith('image/')) {
  format = 'image';
  mimeType = contentType.split(';')[0];
} else if (contentType.includes('pdf')) {
  format = 'pdf';
  mimeType = 'application/pdf';
} else if (contentType.includes('wordprocessingml') || contentType.includes('msword') || fileName.toLowerCase().endsWith('.docx') || fileName.toLowerCase().endsWith('.doc')) {
  format = 'docx';
  mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
} else {
  const bin = inp.binary?.data;
  if (bin && bin.data) {
    const first4 = Buffer.from(bin.data, 'base64').slice(0, 4).toString('hex');
    if (first4.startsWith('89504e47')) { format = 'image'; mimeType = 'image/png'; }
    else if (first4.startsWith('ffd8ff')) { format = 'image'; mimeType = 'image/jpeg'; }
    else if (first4.startsWith('25504446')) { format = 'pdf'; mimeType = 'application/pdf'; }
    else if (first4.startsWith('504b0304')) { format = 'docx'; mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'; }
  }
}
const itemId = $('Extract File URL').first().json.itemId;
return [{ json: { itemId, format, mimeType, fileName }, binary: inp.binary }];

const inp = $input.first();
const binary = inp.binary?.data;
if (!binary) throw new Error('Missing binary data in Build AI Content');
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const b64 = buffer.toString('base64');
const detected = $('Detect Format').first().json;
const { itemId, format, fileName } = detected;
let contentPart;
if (format === 'image') {
  contentPart = { type: 'image_url', image_url: { url: `data:${detected.mimeType};base64,${b64}`, detail: 'high' } };
} else {
  const cleanName = (fileName || 'quotation').replace(/\.(docx|doc)$/i, '.pdf');
  contentPart = { type: 'file', file: { filename: cleanName.endsWith('.pdf') ? cleanName : cleanName + '.pdf', file_data: `data:application/pdf;base64,${b64}` } };
}
const systemPrompt = "You extract tent quotation data. CRITICAL RULES: (1) Find EVERY line item in ALL pricing tables — do not stop after the first row. A quotation typically has 2-5 line items (main product, awnings, transportation, installation, accessories). (2) A single document may contain MULTIPLE separate quotations — extract each as its own object in the quotations array. Look for section breaks, separate quotation numbers, or 'Quotation 1 / Quotation 2' markers. (3) Output ONLY valid JSON, no markdown. Missing text → empty string; missing numbers → 0. Currency values as plain numbers (no RM/comma). Dates as YYYY-MM-DD.";
const taxonomy = `Reference taxonomy — snap the value to the closest match when possible; otherwise output what the quotation says.
- width: 3m, 6m, 9m, 15m, 19m, 20m, 25m, 30m, 40m, 50m, 60m, CM
- length: 5m, 10m, 15m, 20m, 25m, 30m, 35m, 40m, 45m, 50m, Continuous +5m, CM
- frame: Aluminium
- profile: 80mm x 60mm (CM), 98mm x 60mm, 155mm x 60mm, 158mm x 60mm, 158mm x 89mm (CM), 210mm x 112mm, 255mm x 120mm, 300mm x 125mm, 350mm x 125mm
- canvas_material: BO1100-HSH850, BO1100-SX800, TPT-HSB080
- colour: White, Grey, Grey White, Blue Grey, Red Grey, Clear
- structure: Temporary, Semi-Permanent, Temporary (CM), Semi-Permanent (CM)
- corner_type: T1-Fitting, T2-Side Plate, T3-Side Plate
- side_support_type: Side Cable, Side Support Beam, Cross support frame, 2D truss
- qty_side_support: 1 bay, 2 bay, 3 bay, and more
- ground_anchoring: Spike, Wall Plug, Chemical Bolt, J-Bolt, Concreate Footing, Counter Weight (Concrete Block), Counter Weight (Connection Plate)
- roof_canvas: Standard cutting, CM Cutting, c/w separate canvas flap, c/w overlap canvas flap
- sidewall_option: Canvas sidewall c/w liners wall hook, Canvas sidewall c/w 1 french window, Canvas sidewall c/w 2 french window, Canvas sidewall c/w 3 side liner (CM), Hard Panel Sidewall complete set, Glass panel sidewall complete set
- gable_end_canvas: 1 pcs, 2 pcs, No
- gable_end_canvas_details: Std Cutting, Printing Cutting, c/w window, c/w tensioning cable, c/w tensioning complete set
- gable_end_structure: 1 set, 2 set, No
- gutter: Canvas Gutter c/w wall hook, PVC Gutter c/w hook bracket, Zinc Gutter c/w pvc down pipe (CM), No
- door: Double Door, Single Door, Super Double Door, Super Single Door, Roller Shutter, Industrial Sliding Door, Motorize Shutter Door
- accessories: Roof Underlay, Gable End Underlay, Sidewall Underlay, Aluminium Foil, 50 inch Industrial Ventilation Fan, Highbay LED c/w wiring`;
const userText = `Extract quotation data as JSON. CRITICAL: (a) look at EVERY row in the pricing table and include ALL line items; (b) if the document has multiple quotations (separate quotation numbers/sections), each is its own object in the quotations array.

${taxonomy}

Product family guidance: 'product_family' is the base product name for grouping SKU variants across quotations (e.g. 'Aluminium Free Span Structure'). 'product_variant_name' is the full descriptive name from the quotation (e.g. '6m x 15m Aluminium Free Span Structure, extendible in 5m bays'). For non-tent lines like 'Awning c/w column', 'Transportation', 'Installation' — use the closest generic family (e.g. 'Awning', 'Transportation & Installation'). Quantity: numeric quantity from the quotation table (default 1 if unclear). Unit measure: 'block', 'set', 'job', 'pcs' — as shown in the quotation table (default 'pcs').

Schema:
{
  "quotations": [
    {
      "quotation_ref": string,
      "quotation_date": string (YYYY-MM-DD),
      "grand_total_rm": number,
      "line_items": [
        {
          "line_no": number,
          "product_family": string,
          "product_variant_name": string,
          "unit_price_rm": number,
          "line_total_rm": number,
          "quantity": number,
          "unit_measure": string,
          "specs": {
            "width": string, "length": string, "frame": string, "profile": string,
            "canvas_material": string, "colour": string, "structure": string,
            "corner_type": string, "side_support_type": string, "qty_side_support": string,
            "ground_anchoring": string, "roof_canvas": string, "sidewall": string,
            "sidewall_option": string, "gable_end_canvas": string,
            "gable_end_canvas_details": string, "gable_end_structure": string,
            "gutter": string, "door": string, "door_qty": string, "accessories": string
          }
        }
      ]
    }
  ]
}`;
const aiBody = {
  model: 'gpt-5.5',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: [ { type: 'text', text: userText }, contentPart ] }
  ],
  max_completion_tokens: 16000,
  response_format: { type: 'json_object' }
};
return [{ json: { itemId, format, fileName, aiBody } }];

// Combined: parse AI response, per line item find/create Parent + SKU (catalog), then update/add SPA item, then add product row.
const BASE = $env.BITRIX_TFSSB_URL;
const PROP = { WIDTH:100, LENGTH:102, FRAME:104, PROFILE:106, CANVAS_MATERIAL:108, COLOUR:110, STRUCTURE:112, CORNER_TYPE:114, SIDE_SUPPORT_TYPE:116, QTY_SIDE_SUPPORT:118, GROUND_ANCHORING:120, ROOF_CANVAS:122, SIDEWALL:124, SIDEWALL_OPTION:126, GABLE_END_CANVAS:128, GABLE_END_CANVAS_DETAILS:130, GABLE_END_STRUCTURE:132, GUTTER:134, DOOR:136, DOOR_QTY:138, ACCESSORIES:140, QUOTATION_REF:142 };
const PARENT_LINK = 46;
const SPA_ENTITY_TYPE_ID = 1038;
const SPA_CATEGORY_ID = 16;
const PRODUCTROW_OWNER_TYPE = 'T40e'; // SYMBOL_CODE_SHORT for entityTypeId 1038

async function bx(method, body) {
  const r = await this.helpers.httpRequest({
    method: 'POST', url: `${BASE}/${method}`,
    headers: {'Content-Type':'application/json'},
    body: JSON.stringify(body || {}), json: false
  });
  return typeof r === 'string' ? JSON.parse(r) : r;
}

// Parse AI
const resp = $input.first().json;
const raw = resp.choices?.[0]?.message?.content;
if (!raw) throw new Error('OpenAI returned no content');
let data;
try { data = typeof raw === 'string' ? JSON.parse(raw) : raw; }
catch (e) { throw new Error('AI JSON parse failed: ' + String(raw).slice(0, 300)); }
const origItemId = $('Detect Format').first().json.itemId;
const quotations = data.quotations || (data.line_items ? [{ quotation_ref: data.quotation_ref, quotation_date: data.quotation_date, grand_total_rm: data.grand_total_rm, line_items: data.line_items }] : []);
if (quotations.length === 0) throw new Error('AI returned no quotations');

// Pre-clean: delete existing product rows on original SPA (with retry — Bitrix delete sometimes silently fails)
for (let attempt = 0; attempt < 4; attempt++) {
  const existingRowsResp = await bx.call(this, 'crm.item.productrow.list', { filter: { '=ownerType': PRODUCTROW_OWNER_TYPE, '=ownerId': origItemId } });
  const existingRows = existingRowsResp.result?.productRows || [];
  if (existingRows.length === 0) break;
  for (const row of existingRows) {
    await bx.call(this, 'crm.item.productrow.delete', { id: row.id });
  }
}

const results = [];
let firstUsed = false;

for (let qIdx = 0; qIdx < quotations.length; qIdx++) {
  const q = quotations[qIdx];
  const lines = q.line_items || [];
  let currentSpaId = null;
  for (let lIdx = 0; lIdx < lines.length; lIdx++) {
    const li = lines[lIdx];
    const productFamily = String(li.product_family || li.product || 'Unnamed').trim().slice(0, 250);
    const productVariantName = String(li.product_variant_name || li.product || 'Unnamed Variant').trim().slice(0, 250);
    const specs = li.specs || {};
    const quantity = li.quantity || 1;
    const unitPrice = li.unit_price_rm || 0;
    const lineTotal = li.line_total_rm || 0;
    const unitMeasure = li.unit_measure || 'pcs';
    const quotationRef = q.quotation_ref || '';
    const quotationDate = q.quotation_date || null;
    const grandTotal = q.grand_total_rm || 0;

    // 1. Find or create parent product (iblock 14)
    let parentId;
    const parentFind = await bx.call(this, 'catalog.product.list', {
      select: ['id','name','iblockId'],
      filter: { iblockId: 14, '=name': productFamily }
    });
    const parentMatches = parentFind.result?.products || [];
    if (parentMatches.length > 0) {
      parentId = parentMatches[0].id;
    } else {
      const parentAdd = await bx.call(this, 'catalog.product.add', {
        fields: { iblockId: 14, name: productFamily, active: 'Y' }
      });
      parentId = parentAdd.result?.element?.id;
      if (!parentId) throw new Error('Parent create failed: ' + JSON.stringify(parentAdd));
    }

    // 2. Find or create SKU offer (iblock 16) with attributes
    let skuId;
    const skuFind = await bx.call(this, 'catalog.product.list', {
      select: ['id','name','iblockId'],
      filter: { iblockId: 16, '=name': productVariantName }
    });
    const skuMatches = skuFind.result?.products || [];
    if (skuMatches.length > 0) {
      skuId = skuMatches[0].id;
    } else {
      const skuFields = {
        iblockId: 16, name: productVariantName, active: 'Y',
        [`property${PARENT_LINK}`]: { value: parentId }
      };
      const specMap = {
        WIDTH: specs.width, LENGTH: specs.length, FRAME: specs.frame, PROFILE: specs.profile,
        CANVAS_MATERIAL: specs.canvas_material, COLOUR: specs.colour, STRUCTURE: specs.structure,
        CORNER_TYPE: specs.corner_type, SIDE_SUPPORT_TYPE: specs.side_support_type,
        QTY_SIDE_SUPPORT: specs.qty_side_support, GROUND_ANCHORING: specs.ground_anchoring,
        ROOF_CANVAS: specs.roof_canvas, SIDEWALL: specs.sidewall, SIDEWALL_OPTION: specs.sidewall_option,
        GABLE_END_CANVAS: specs.gable_end_canvas, GABLE_END_CANVAS_DETAILS: specs.gable_end_canvas_details,
        GABLE_END_STRUCTURE: specs.gable_end_structure, GUTTER: specs.gutter, DOOR: specs.door,
        DOOR_QTY: specs.door_qty, ACCESSORIES: specs.accessories, QUOTATION_REF: quotationRef
      };
      for (const [k,v] of Object.entries(specMap)) {
        if (v && String(v).trim()) skuFields[`property${PROP[k]}`] = { value: String(v) };
      }
      const skuAdd = await bx.call(this, 'catalog.product.add', { fields: skuFields });
      skuId = skuAdd.result?.element?.id;
      if (!skuId) throw new Error('SKU create failed: ' + JSON.stringify(skuAdd));
    }

    // 3. SPA update or add — first line of first quotation updates original SPA; all other lines within same q share same SPA (add product row only); new quotation → create new SPA on its first line, then add subsequent rows to that.
    // Behavior chosen: each quotation = 1 SPA item. Lines of q populate its Products tab.
    const specFields = {
      ufCrm8Qref: quotationRef,
      ufCrm8QuotationDate: quotationDate,
      ufCrm8GrandTotalRm: grandTotal,
      ufCrm8LineItemNo: 1,  // main-line indicator; will be set to line 1's values for the SPA summary
    };
    // Only populate spec fields from line 1 (main product summary)
    if (lIdx === 0) {
      Object.assign(specFields, {
        ufCrm8Product: productVariantName,
        ufCrm8UnitPriceRm: unitPrice,
        ufCrm8LineTotalRm: lineTotal,
        ufCrm8Width: specs.width || '',
        ufCrm8Length: specs.length || '',
        ufCrm8Frame: specs.frame || '',
        ufCrm8Profile: specs.profile || '',
        ufCrm8CanvasMaterial: specs.canvas_material || '',
        ufCrm8Colour: specs.colour || '',
        ufCrm8StructureStr: specs.structure || '',
        ufCrm8CornerTypeStr: specs.corner_type || '',
        ufCrm8SideSupportTypeStr: specs.side_support_type || '',
        ufCrm8QtySideSupport: specs.qty_side_support || '',
        ufCrm8GroundAnchoringS: specs.ground_anchoring || '',
        ufCrm8RoofCanvas: specs.roof_canvas || '',
        ufCrm8Sidewall: specs.sidewall || '',
        ufCrm8SidewallOption: specs.sidewall_option || '',
        ufCrm8GableEndCanvasS: specs.gable_end_canvas || '',
        ufCrm8GableEndCanvasDetails: specs.gable_end_canvas_details || '',
        ufCrm8GableEndStructureS: specs.gable_end_structure || '',
        ufCrm8Gutter: specs.gutter || '',
        ufCrm8Door: specs.door || '',
        ufCrm8DoorQty: specs.door_qty || '',
        ufCrm8Accessories: specs.accessories || ''
      });
    }

    if (lIdx === 0) {
      // First line of this quotation — decide update vs add SPA
      if (qIdx === 0 && !firstUsed) {
        // Update original SPA
        const updResp = await bx.call(this, 'crm.item.update', { entityTypeId: SPA_ENTITY_TYPE_ID, id: origItemId, fields: specFields });
        currentSpaId = updResp.result?.item?.id || origItemId;
        firstUsed = true;
      } else {
        // Add new SPA (subsequent quotation)
        const addResp = await bx.call(this, 'crm.item.add', { entityTypeId: SPA_ENTITY_TYPE_ID, fields: { ...specFields, title: `${quotationRef || 'Quotation'} — ${productFamily}`, categoryId: SPA_CATEGORY_ID } });
        currentSpaId = addResp.result?.item?.id;
        if (!currentSpaId) throw new Error('SPA add failed: ' + JSON.stringify(addResp));
      }
    }

    // 4. Add product row on currentSpaId with SKU
    const rowResp = await bx.call(this, 'crm.item.productrow.add', {
      fields: {
        ownerType: PRODUCTROW_OWNER_TYPE, ownerId: currentSpaId,
        productId: skuId, price: unitPrice, quantity: quantity
      }
    });
    const rowId = rowResp.result?.productRow?.id;

    results.push({ json: { qIdx, lIdx, spaId: currentSpaId, parentId, skuId, rowId, productFamily, productVariantName, unitPrice, quantity } });
  }
}
return results;

